font_t get_font(font_type_e type)
{
    switch (type)
    {
        case FONT_TYPE_ROBOTO32: return ROBOTO32;
        default:
            LOG_ERROR("Font type does not exist.");
    }
    return (font_t){ 0 };
}

static s32 get_codepoint_index(font_char_t* chars, s32 codepoint, s32 start, s32 end)
{
    for (s32 i = start; i <= end; i++)
    {
        if (chars[i].codepoint == codepoint) return i;
    }
    return -1;
}

font_char_t font_get_codepoint_data(font_type_e font_type, s32 codepoint)
{
    font_t font = get_font(font_type);

    s32 index = get_codepoint_index(font.chars, codepoint, 0, font.char_count - 1);
    font_char_t c = { 0 };

    if (index == -1)
    {
        LOG_ERROR("Codepoint not recognized.");
        return c;
    }

    c = font.chars[index]; 
    return c;
}

rectangle_t font_get_rect_from_codepoint(font_type_e font_type, s32 codepoint)
{
    font_t font = get_font(font_type);

    s32 index = get_codepoint_index(font.chars, codepoint, 0, font.char_count - 1);
    rectangle_t rect = { 0 };

    if (index == -1)
    {
        LOG_ERROR("Codepoint not recognized.");
        return rect;
    }

    font_char_t c = font.chars[index]; 
    rect = rectangle((f32)c.x / (f32)font.w, (f32)c.y / (f32)font.h, (f32)c.w / (f32)font.w, (f32)c.h / (f32)font.h, 0);

    return rect;
}

f32 font_get_width(font_type_e font_type)
{
    return (f32)get_font(font_type).w;
}

f32 font_get_height(font_type_e font_type)
{
    return (f32)get_font(font_type).h;
}
